const visual = {
  prepare: function (input) {
    return [{ kind: 'text', payload: '3:1' }];
  },
  render: function (input, metrics) {
    var vw = input.viewport.widthDu;
    var vh = input.viewport.heightDu;
    var width = vw > 0 ? vw : 800;
    var height = vh > 0 ? vh : 600;
    var marginX = width * 0.15;
    var x0 = marginX;
    var x1 = width - marginX;
    var y = height * 0.56;
    var total = x1 - x0;
    var split = x0 + total * 0.75;
    var barH = Math.max(3, Math.min(width, height) * 0.012);
    var tickH = barH * 4;
    var color = '#26354a';

    function rect(x, top, w, h) {
      return [
        ['M', x, top],
        ['L', x + w, top],
        ['L', x + w, top + h],
        ['L', x, top + h],
        ['Z']
      ];
    }

    var left = rect(x0, y - barH / 2, split - x0, barH);
    var right = rect(split, y - barH / 2, x1 - split, barH);
    var divider = rect(split - barH * 0.75, y - tickH / 2, barH * 1.5, tickH);
    var labelY = y - Math.max(28, Math.min(width, height) * 0.07);

    return {
      schemaVersion: 1,
      sceneId: 'ratio-3-to-1',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: width, height: height },
      paths: [
        { id: 'segment-3', commands: left },
        { id: 'segment-1', commands: right },
        { id: 'divider', commands: divider }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'segment-3', fill: color },
          { type: 'path', pathId: 'segment-1', fill: color },
          { type: 'path', pathId: 'divider', fill: color },
          {
            type: 'label',
            contentId: metrics[0].contentId,
            anchor: { x: (x0 + x1) / 2, y: labelY },
            hAlign: 'center',
            vAlign: 'bottom',
            color: color
          }
        ]
      }
    };
  }
};
